import asyncio

def blocking_lookup(key: str) -> str:
    # Placeholder for a synchronous file or network SDK call.
    return f"value-for-{key}"

async def handler(key: str) -> str:
    return await asyncio.to_thread(blocking_lookup, key)

import asyncio

async def get_profile(client, user_id: str):
    try:
        return await asyncio.wait_for(
            client.fetch_profile(user_id),
            timeout=2.0,
        )
    except asyncio.TimeoutError:
        # Translate or record a timeout at the appropriate boundary.
        raise
